async ({ workspace: { read, edit } }, p: { tail: string }) => {
  const live = "test/extension/raw-grammar-live.test.ts";
  const prov = "test/support/raw-call-provider.js";
  const [a, b] = await Promise.all([read(live), read(prov)]);
  const rows = (c: string) => c.split("\n").map((l) => { const k = l.indexOf("|"); return { a: l.slice(0, k), t: l.slice(k + 1) }; });
  const la = rows(a.content), lb = rows(b.content);
  const s = la.findIndex((l) => l.t.startsWith('it("coerces save-only'));
  const lastIdx = la.length - 1 - [...la].reverse().findIndex((l) => l.t.trim() !== "");
  const ps = lb.findIndex((l) => l.t.includes('"run save-coercion fixture": {'));
  const pi = lb.findIndex((l) => l.t.includes('"run invalid fixture": {'));
  const pt = lb.findIndex((l) => l.t.includes('"run type-invalid fixture": {'));
  const pend = lb.findIndex((l, i) => i > pt && l.t === "};");
  await Promise.all([
    edit(live, { revision: a.revision, changes: [{ kind: "replace", start: la[s].a, end: la[lastIdx].a, content: p.tail }] }),
    edit(prov, { revision: b.revision, changes: [
      { kind: "delete", start: lb[ps].a, end: lb[pi - 1].a },
      { kind: "delete", start: lb[pt].a, end: lb[pend - 1].a },
    ] }),
  ]);
  const nb = await read(prov, { format: "raw", limit: 30 });
  return nb.content;
}

